import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1788283606000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>OPENGIST_URL</code></td><td>yes</td><td>—</td><td>Root URL of the instance, e.g. <code>https://gist.example.com</code></td></tr><tr><td><code>OPENGIST_TOKEN</code></td><td>yes</td><td>—</td><td>Personal Access Token, starts with <code>og_</code></td></tr><tr><td><code>OPENGIST_READ_ONLY</code></td><td>no</td><td><code>false</code></td><td><code>true</code> registers only the eight read tools</td></tr><tr><td><code>OPENGIST_INSECURE_TLS</code></td><td>no</td><td><code>false</code></td><td><code>true</code> accepts self-signed certificates on the Opengist connection only</td></tr><tr><td><code>ELICITATION</code></td><td>no</td><td><code>true</code></td><td><code>false</code> replaces the approval dialog with the two-call token. <strong>Not prefixed</strong></td></tr></tbody></table><p>Only the exact string <code>true</code> enables a boolean. <code>1</code>, <code>yes</code> and <code>TRUE</code> are false.</p><h2 id="opengist-url" tabindex="-1"><code>OPENGIST_URL</code> <a class="header-anchor" href="#opengist-url" aria-label="Permalink to “OPENGIST_URL”">​</a></h2><p>The root of the instance, not the API path. A trailing slash is stripped, and a trailing <code>/api</code> is accepted and removed rather than producing <code>/api/api</code>.</p><p>The server exits at startup if the value is not a valid URL, uses a protocol other than <code>http:</code>/<code>https:</code>, or contains a username or password. It warns and continues for plain <code>http://</code> to a non-loopback host — the token and every gist would travel unencrypted.</p><h2 id="opengist-token" tabindex="-1"><code>OPENGIST_TOKEN</code> <a class="header-anchor" href="#opengist-token" aria-label="Permalink to “OPENGIST_TOKEN”">​</a></h2><p>Created in the web UI under <strong>Settings → Access Tokens</strong>. Scopes: <code>gist:read</code>, <code>gist:write</code>, <code>user:read</code>, and <code>user:write</code> for <code>set_gist_like</code>. See <a href="/guide/configuration#required-scopes">Configuration</a> — a token without <code>gist:read</code> does not fail, it silently returns only public gists.</p><p>The value is read once at startup and then removed from <code>process.env</code>, so it is not inherited by child processes and does not appear in <code>/proc/&lt;pid&gt;/environ</code>.</p><p>A token that does not start with <code>og_</code> produces a warning: the usual cause is an account password pasted in its place.</p><h2 id="opengist-read-only" tabindex="-1"><code>OPENGIST_READ_ONLY</code> <a class="header-anchor" href="#opengist-read-only" aria-label="Permalink to “OPENGIST_READ_ONLY”">​</a></h2><p><code>true</code> means <code>create_gist</code>, <code>update_gist</code>, <code>delete_gist_files</code>, <code>delete_gist</code>, <code>fork_gist</code> and <code>set_gist_like</code> are never registered. The model does not see them.</p><p>This is a guard rail in this process, not a boundary — the boundary is the token&#39;s scopes. See <a href="/guide/security#what-actually-holds">Security</a>.</p><h2 id="elicitation" tabindex="-1"><code>ELICITATION</code> <a class="header-anchor" href="#elicitation" aria-label="Permalink to “ELICITATION”">​</a></h2><p>Whether a client that <em>can</em> show a dialog is asked before a guarded tool acts. Default <code>true</code>. <code>false</code> takes the two-call-token path instead — it does not remove the guard, and a server started with it off prints one line saying so.</p><p>Two ways it differs from every other variable here:</p><ul><li><strong>No prefix.</strong> One <code>export ELICITATION=false</code> reaches every MCP server in the same environment, not just this one. That is the point of it and also its risk; see <a href="/guide/approval">Asking a person</a>.</li><li><strong>Fatal on anything else.</strong> Where the <code>OPENGIST_*</code> booleans fail <em>off</em> on a typo, this one stops the server with exit code 1. It is the only variable here that defaults to <em>on</em>, and a typo that fell back would leave the dialog running while you believed it was off.</li></ul><p>Values are trimmed and matched case-insensitively. It is read <em>after</em><code>OPENGIST_TOKEN</code> is deleted from <code>process.env</code>, so the fatal path cannot leave the token sitting there for a crash reporter.</p><h2 id="opengist-insecure-tls" tabindex="-1"><code>OPENGIST_INSECURE_TLS</code> <a class="header-anchor" href="#opengist-insecure-tls" aria-label="Permalink to “OPENGIST_INSECURE_TLS”">​</a></h2><p><code>true</code> disables certificate validation <strong>for connections to <code>OPENGIST_URL</code> only</strong>, through a dedicated undici dispatcher. <code>NODE_TLS_REJECT_UNAUTHORIZED</code> is never set, so no other request the process makes is affected, and the relaxed dispatcher is only selected when the request origin matches the configured instance.</p><p>Prefer installing the CA certificate in the system trust store, or <code>NODE_EXTRA_CA_CERTS</code>, where that is possible.</p><h2 id="starting-without-credentials" tabindex="-1">Starting without credentials <a class="header-anchor" href="#starting-without-credentials" aria-label="Permalink to “Starting without credentials”">​</a></h2><p>If <code>OPENGIST_URL</code> or <code>OPENGIST_TOKEN</code> is missing, the server prints the setup instructions to stderr and <strong>still starts</strong>. It completes the MCP handshake and answers <code>tools/list</code>; every tool call then fails with the same instructions without making a request.</p><p>This is deliberate: registries and sandbox inspectors start the server without secrets, and could not enumerate the tool surface otherwise.</p><h2 id="narrowing-the-tool-list" tabindex="-1">Narrowing the tool list <a class="header-anchor" href="#narrowing-the-tool-list" aria-label="Permalink to “Narrowing the tool list”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>OPENGIST_ALLOW_TOOLS</code></td><td>no</td><td>Tool names, <code>list_*</code> prefixes or <code>essential</code>; only these register</td></tr><tr><td><code>OPENGIST_DENY_TOOLS</code></td><td>no</td><td>Same syntax; subtracted from whatever the allow list left</td></tr></tbody></table><p>Both are comma-separated. Each entry is either an exact tool name or a prefix with a single trailing <code>*</code>. Entries are trimmed and matched case-insensitively; empty entries are ignored, and a value that is empty or only whitespace counts as unset — <code>OPENGIST_ALLOW_TOOLS=</code> in a compose file does not mean &quot;allow nothing&quot;. <code>essential</code> is recognised only in the allow list, and selects <code>list_gists</code>, <code>search_gists</code>, <code>get_gist</code>, <code>get_gist_file</code>, <code>create_gist</code>, <code>update_gist</code>, <code>delete_gist</code>.</p><p><strong>An entry that matches no tool aborts startup</strong>, naming the entry and listing the valid names, as does a malformed pattern such as <code>*_x</code> or <code>list_*_x</code>. The alternative — ignoring the entry — leaves a tool missing from <code>tools/list</code> with nothing pointing at the cause. If both lists together remove everything, the server refuses to start rather than offering an empty tool list.</p><p>Under <code>OPENGIST_READ_ONLY</code>, an exact write-tool name in the allow list is an error naming the read-only setting rather than &quot;unknown tool&quot;; a pattern covering write tools is accepted and merely contributes nothing, with a warning on stderr. Deny entries are exempt: denying an already-suppressed tool is how a defensive list is written.</p>`,29)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};